const input = $json.body ?? $json;
const allowedSources = ['source_1_placeholder', 'source_2_placeholder', 'source_3_placeholder'];
const fixtureEvidence = [{ requirement: 'APIs y automatización', evidence_url: 'https://jobs.example.invalid/requisitos/apis', verified_at: '2026-09-28T12:00:00Z' }];
const fixture = [
  { source_name: 'test_fixture', source_reference: 'fixture-001', job_url: 'https://jobs.example.invalid/nube/ai-automation-engineer?utm_source=test', company: 'Nube Ejemplo', title: 'AI Automation Engineer', country_code: 'CO', location: 'Remoto Colombia', modality: 'remoto_colombia_latam', posted_at: '2026-09-28', vacancy_summary: 'Vacante ficticia para automatización con APIs verificable en el enlace de evidencia.', requirement_evidence: fixtureEvidence, verified_at: '2026-09-28T12:00:00Z' },
  { source_name: 'test_fixture', source_reference: 'fixture-002', job_url: 'https://jobs.example.invalid/flujo/automation-developer', company: 'Flujo Ficticio', title: 'Automation Developer', country_code: 'CO', location: 'Remoto Colombia', modality: 'remoto_colombia_latam', posted_at: '2026-09-28', vacancy_summary: 'Vacante ficticia de desarrollo de automatización con requisitos enlazados.', requirement_evidence: fixtureEvidence, verified_at: '2026-09-28T12:00:00Z' },
  { source_name: 'test_fixture', source_reference: 'fixture-003', job_url: 'https://jobs.example.invalid/prisma/implementation-specialist', company: 'Prisma Demo', title: 'Implementation Specialist', country_code: 'US', location: 'Remote LATAM', modality: 'contractor_internacional', posted_at: '2026-09-28', vacancy_summary: 'Vacante ficticia de implementación con evidencia de requisitos públicos.', requirement_evidence: fixtureEvidence, verified_at: '2026-09-28T12:00:00Z' },
  { source_name: 'test_fixture', source_reference: 'fixture-004', job_url: 'https://jobs.example.invalid/nube/ai-automation-engineer?ref=board-b', company: 'Nube Ejemplo', title: 'AI Automation Engineer', country_code: 'CO', location: 'Remoto Colombia', modality: 'remoto_colombia_latam', posted_at: '2026-09-28', vacancy_summary: 'Vacante ficticia para automatización con APIs verificable en el enlace de evidencia.', requirement_evidence: fixtureEvidence, verified_at: '2026-09-28T12:00:00Z' }
];
const testMode = input.test_mode === true || $execution.mode === 'manual';
const records = testMode ? fixture : input.source_records;
if (!Array.isArray(records) || records.length === 0) throw new Error('No hay registros de entrada. El modo productivo exige source_records del contrato.');
const sources = [...new Set(records.map((record) => record.source_name))];
if (sources.length > 3) throw new Error('El MVP permite como máximo tres fuentes por ejecución.');
if (!testMode && sources.some((source) => !allowedSources.includes(source))) throw new Error('Fuente no aprobada. Registrar y activar la fuente antes de ingerir.');
return records.map((record) => ({ json: { ...record, test_mode: testMode } }));

const required = ['source_name', 'source_reference', 'job_url', 'company', 'title', 'country_code', 'modality', 'vacancy_summary', 'verified_at'];
for (const field of required) {
  if (typeof $json[field] !== 'string' || !$json[field].trim()) throw new Error(`Campo obligatorio inválido: ${field}`);
}
if (!/^[A-Z]{2}$/.test($json.country_code.trim().toUpperCase())) throw new Error('country_code debe ser ISO-3166 alpha-2.');
if (Number.isNaN(Date.parse($json.verified_at))) throw new Error('verified_at debe ser fecha/hora ISO válida.');
const normalizeText = (value) => value.trim().toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, ' ').trim().replace(/\s+/g, ' ');
const canonicalUrl = (value) => {
  const url = new URL(value.trim());
  if (!['https:', 'http:'].includes(url.protocol)) throw new Error('La URL debe usar HTTP(S).');
  url.hash = '';
  for (const key of [...url.searchParams.keys()]) {
    if (/^(utm_[a-z]+|ref|source|trk|tracking|fbclid|gclid)$/i.test(key)) url.searchParams.delete(key);
  }
  url.hostname = url.hostname.toLowerCase();
  url.pathname = url.pathname.replace(/\/{2,}/g, '/').replace(/\/$/, '') || '/';
  return url.toString().replace(/\/$/, '');
};
const summary = $json.vacancy_summary.trim().replace(/\s+/g, ' ');
if (summary.length < 20 || summary.length > 4000 || /<[^>]+>/.test(summary)) throw new Error('vacancy_summary debe ser texto verificable de 20 a 4000 caracteres, sin HTML.');
if (!Array.isArray($json.requirement_evidence) || $json.requirement_evidence.length === 0 || $json.requirement_evidence.length > 20) throw new Error('requirement_evidence debe ser un arreglo de 1 a 20 evidencias.');
const requirement_evidence = $json.requirement_evidence.map((evidence) => {
  if (!evidence || typeof evidence.requirement !== 'string' || !evidence.requirement.trim() || evidence.requirement.trim().length > 500) throw new Error('Cada evidencia requiere requirement de máximo 500 caracteres.');
  if (typeof evidence.evidence_url !== 'string' || Number.isNaN(Date.parse(evidence.verified_at))) throw new Error('Cada evidencia requiere evidence_url y verified_at ISO.');
  return { requirement: evidence.requirement.trim().replace(/\s+/g, ' '), evidence_url: canonicalUrl(evidence.evidence_url), verified_at: new Date(evidence.verified_at).toISOString() };
});
const company = $json.company.trim().replace(/\s+/g, ' ');
const title = $json.title.trim().replace(/\s+/g, ' ');
const countryCode = $json.country_code.trim().toUpperCase();
const modality = $json.modality.trim();
const canonical_url = canonicalUrl($json.job_url);
const dedupe_basis = `${normalizeText(company)}|${normalizeText(title)}|${countryCode.toLowerCase()}|${normalizeText(modality)}`;
return [{ json: { source_key: $json.source_name.trim().toLowerCase(), source_reference: $json.source_reference.trim(), canonical_url, company, title, country_code: countryCode, location: ($json.location ?? '').trim().replace(/\s+/g, ' '), modality, posted_at: $json.posted_at ?? null, vacancy_summary: summary, requirement_evidence, verified_at: new Date($json.verified_at).toISOString(), dedupe_basis, test_mode: $json.test_mode } }];
